import React, { useContext } from 'react';
import { Link } from 'react-router-dom';
import { courses } from '../data/courses';
import { AuthContext } from '../context/AuthContext';
import Navbar from '../components/Navbar';

// Simulation de progression par cours, en attendant le vrai backend
const enrolledProgress = {
  1: { completed: 1, total: 2 },
  2: { completed: 0, total: 2 },
};

const Dashboard = () => {
  const { user } = useContext(AuthContext);
  const enrolledCourses = courses.filter(c => enrolledProgress[c.id]);

  return (
    <div className="min-h-screen bg-[#0A0E1A] text-white">
      <Navbar />

      <div className="max-w-4xl mx-auto px-6 py-16">
        <h1 className="text-2xl font-bold mb-1">Mon apprentissage</h1>
        <p className="text-slate-500 text-sm mb-10">
          Content de te revoir{user?.email ? `, ${user.email.split('@')[0]}` : ''}.
        </p>

        {enrolledCourses.length > 0 ? (
          <div className="space-y-4">
            {enrolledCourses.map(course => {
              const progress = enrolledProgress[course.id];
              const percent = Math.round((progress.completed / progress.total) * 100);

              return (
                <div
                  key={course.id}
                  className="bg-slate-900/60 border border-slate-800 rounded-2xl p-6 hover:border-blue-500/40 transition-colors duration-300"
                >
                  <div className="flex items-center justify-between mb-4">
                    <div>
                      <span className={`text-[11px] font-bold uppercase tracking-wide px-3 py-1 rounded-full ${
                        course.isFree ? 'bg-emerald-500/10 text-emerald-400' : 'bg-blue-500/10 text-blue-400'
                      }`}>
                        {course.isFree ? 'Gratuit' : 'Premium'}
                      </span>
                      <h3 className="text-lg font-bold mt-3">{course.title}</h3>
                    </div>
                    <Link
                      to="/player"
                      className="bg-blue-600 hover:bg-blue-500 text-white font-semibold text-sm px-5 py-2.5 rounded-lg transition-colors shrink-0"
                    >
                      Continuer
                    </Link>
                  </div>

                  <div className="w-full bg-slate-800 h-2 rounded-full overflow-hidden">
                    <div
                      className="h-full bg-gradient-to-r from-blue-600 to-cyan-500 rounded-full transition-all duration-500"
                      style={{ width: `${percent}%` }}
                    ></div>
                  </div>
                  <p className="text-xs text-slate-500 mt-2">
                    {progress.completed} / {progress.total} leçons — {percent}% complété
                  </p>
                </div>
              );
            })}
          </div>
        ) : (
          <div className="border border-dashed border-slate-800 rounded-2xl p-12 text-center">
            <p className="text-slate-500 text-sm mb-4">Tu n'as encore commencé aucune formation.</p>
            <Link to="/catalog" className="text-blue-400 hover:text-blue-300 font-semibold text-sm">
              Découvrir le catalogue →
            </Link>
          </div>
        )}
      </div>
    </div>
  );
};
export default Dashboard;
